    <style>
        :root{color-scheme:dark;--bg:#050816;--surface:#0d142bd9;--line:#25314d;--text:#f8fafc;--muted:#a8b5ca;--primary:#6f92ff;--accent:#55e8c4;--shadow:0 25px 80px #0007}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:radial-gradient(circle at 12% -5%,#1a316b 0,transparent 33%),radial-gradient(circle at 96% 18%,#0f594f45 0,transparent 27%),var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.6}body:before{content:"";position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(#fff1 1px,transparent 1px),linear-gradient(90deg,#fff1 1px,transparent 1px);background-size:48px 48px;opacity:.12;mask-image:linear-gradient(#000,transparent 72%)}a{color:inherit}.shell{width:min(1180px,calc(100% - 30px));margin:auto;position:relative}.topbar{position:sticky;top:0;z-index:20;background:#050816df;border-bottom:1px solid var(--line);backdrop-filter:blur(18px)}.nav{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;font-weight:900;letter-spacing:-.02em}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:linear-gradient(145deg,#345bc0,#7a9aff);box-shadow:0 10px 30px #5f8cff4b;font-size:11px}.brand small{display:block;color:#8090aa;font-size:9px;letter-spacing:.12em;text-transform:uppercase}.navlinks{display:flex;align-items:center;gap:7px}.navlinks a{padding:9px 11px;text-decoration:none;color:var(--muted);font-size:13px;font-weight:800;border-radius:10px}.navlinks a:hover{background:#fff1;color:var(--text)}.navlinks .cta-link{border:1px solid #5f8cff45;color:#dbe4ff;background:#5f8cff11}.hero{min-height:calc(100vh - 72px);display:grid;grid-template-columns:minmax(0,1.08fr) minmax(340px,.92fr);align-items:center;gap:clamp(35px,7vw,85px);padding:76px 0}.eyebrow{display:inline-flex;align-items:center;gap:8px;border:1px solid #55e8c43d;background:#55e8c410;color:#a7f5e2;border-radius:999px;padding:7px 10px;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.12em}.eyebrow:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 15px var(--accent)}h1{font-size:clamp(3.2rem,7.8vw,6.5rem);line-height:.9;letter-spacing:-.065em;margin:20px 0}h1 span{background:linear-gradient(90deg,#fff,#9eb4ff 60%,#76efd2);background-clip:text;-webkit-background-clip:text;color:transparent}.hero p{color:var(--muted);max-width:730px;font-size:clamp(1rem,2vw,1.2rem)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:28px}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 16px;border:1px solid var(--line);border-radius:13px;text-decoration:none;font-size:13px;font-weight:900;background:#fff1;transition:.2s}.btn:hover{transform:translateY(-2px);border-color:#708bc9}.btn.primary{background:linear-gradient(135deg,#4c70df,#7898ff);border-color:transparent;box-shadow:0 15px 38px #4d70df3b}.micro{font-size:12px!important;color:#77859e!important}.terminal{border:1px solid var(--line);border-radius:22px;background:linear-gradient(180deg,#0e1731f2,#070b18f6);box-shadow:var(--shadow);overflow:hidden}.terminal-head{height:52px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 16px}.dots{display:flex;gap:6px}.dots i{width:8px;height:8px;border-radius:50%;background:#52607a}.terminal-head span{font:800 10px ui-monospace,monospace;color:#8190a8;letter-spacing:.12em}.terminal-body{padding:22px}.label{font-size:10px;color:#7e8ca4;text-transform:uppercase;font-weight:900;letter-spacing:.12em}.base{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid #5f8cff35;background:#5f8cff0d;border-radius:12px;padding:12px;margin:8px 0 20px}.base code{font-size:12px;overflow-wrap:anywhere}.copy{border:0;border-radius:8px;background:#fff1;color:#dce5ff;padding:7px 9px;font-weight:800;cursor:pointer}pre{margin:0;overflow:auto;color:#d4e0f6;font:12px/1.75 ui-monospace,monospace}.green{color:#83e8cd}.blue{color:#9ab0ff}.muted{color:#60708d}.trust{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--line);border-radius:18px;background:#0b1328aa;overflow:hidden;margin-bottom:94px}.trust div{padding:17px;border-right:1px solid var(--line)}.trust div:last-child{border:0}.trust strong{display:block;font-size:13px}.trust span{display:block;color:var(--muted);font-size:11px}.section{padding:22px 0 88px}.kicker{color:#9bb1ff;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.13em}.section h2{font-size:clamp(2rem,5vw,4rem);line-height:1;letter-spacing:-.05em;margin:8px 0 13px;max-width:850px}.section>.intro{max-width:760px;color:var(--muted);margin-bottom:28px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.card{min-height:190px;border:1px solid var(--line);border-radius:18px;background:var(--surface);padding:20px}.card .icon{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:#5f8cff11;border:1px solid #5f8cff32;color:#b6c6ff;font-weight:900;font-size:12px;margin-bottom:22px}.card h3{margin:0 0 6px}.card p{color:var(--muted);font-size:13px;margin:0}.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,.8fr);gap:18px;border:1px solid #5f8cff30;border-radius:24px;background:linear-gradient(120deg,#5f8cff12,#55e8c407),#0a1125aa;padding:clamp(25px,5vw,45px);box-shadow:var(--shadow)}.split p{color:var(--muted)}.points{display:grid;gap:9px}.point{padding:13px;border:1px solid var(--line);border-radius:12px;background:#060b18a8}.point strong{font-size:13px;display:block}.point span{font-size:12px;color:var(--muted)}.final{margin:65px auto 82px;text-align:center;border:1px solid var(--line);border-radius:25px;padding:clamp(32px,6vw,60px);background:radial-gradient(circle at 50% 0,#5f8cff22,transparent 46%),#0a1125b2}.final h2{margin-left:auto;margin-right:auto}.final p{max-width:650px;margin:0 auto 23px;color:var(--muted)}.final .actions{justify-content:center}.footer{display:flex;justify-content:space-between;gap:15px;border-top:1px solid var(--line);padding:25px 0 45px;color:#7b899f;font-size:12px}.footer-links{display:flex;gap:12px;flex-wrap:wrap}.footer a{text-decoration:none}@media(max-width:900px){.hero{grid-template-columns:1fr;min-height:0}.terminal{max-width:700px}.grid{grid-template-columns:repeat(2,1fr)}.trust{grid-template-columns:repeat(2,1fr)}.trust div{border-bottom:1px solid var(--line)}.split{grid-template-columns:1fr}}@media(max-width:630px){.navlinks a:not(.cta-link){display:none}.hero{padding:52px 0 62px}.actions{flex-direction:column}.btn{width:100%}.grid,.trust{grid-template-columns:1fr}.trust div{border-right:0}.footer{flex-direction:column}.brand small{display:none}}
